if (args.move.weaponType === 'hidden' || args.item?.system?.category === 'sanshou') {
    const tier = args.move.computedTier || args.item?.system?.tier || 1;
    const paozhi = actor.system.skills.paozhi.total || 0;
    if (tier === 1) {
        args.output.damage += (10 + paozhi);
        args.output.bonusDesc.push(`释迦神功 +${10+paozhi}`);
    }
}

if (args.move.weaponType === 'hidden' || args.item?.system?.category === 'sanshou') {
