}

if (args.move.weaponType === 'hidden' || args.item?.system?.category === 'sanshou') {
    const paozhi = actor.system.skills.paozhi.total || 0;
    args.output.damage += (30 + paozhi);
    args.output.bonusDesc.push(`释迦神功 +${30+paozhi}`);
}

const mp = actor.system.resources.mp.value;
const ratio = 1;
if (mp > 100 && ['waigong', 'neigong'].includes(args.type) && args.output.damage > 1) {
    const maxAbsorb = args.output.damage - 1;
    const maxMpCost = Math.ceil(maxAbsorb / ratio);
    const maxAllowedMp = Math.min(maxMpCost, mp);

    if (maxAllowedMp > 0) {
        const htmlContent = `
            <div style="margin-bottom: 10px; color: #555;">
                <p>即将承受 <b>${args.output.damage}</b> 点内外功伤害。</p>
                <p style="color:#e67e22;">每消耗 1 点内力可抵消 ${ratio} 点伤害（最少承受1点伤害）。</p>
            </div>
            <div class="form-group">
                <label style="font-weight:bold;">消耗内力 (0-${maxAllowedMp}):</label>
                <input type="number" name="spendCount" value="${maxAllowedMp}" min="0" max="${maxAllowedMp}" style="text-align:center;">
            </div>
        `;
        const spendResult = await foundry.applications.api.DialogV2.prompt({
            window: { title: "金刚不坏神功 - 护体", icon: "fas fa-shield-alt" },
            content: htmlContent,
            ok: {
                label: "确认",
                icon: "fas fa-check",
                callback: (event, button) => {
                    const fd = new FormData(button.form);
                    return parseInt(fd.get("spendCount")) || 0;
                }
            },
            rejectClose: false
        });

        if (spendResult && spendResult > 0) {
            const finalSpend = Math.min(spendResult, maxAllowedMp);
            const absorb = Math.min(finalSpend * ratio, maxAbsorb);

            args.output.damage -= absorb;
            await actor.changeResources({'system.resources.mp.value': mp - finalSpend}, { cause: "moveCost", source: "script", sourceActor: actor, item: thisItem instanceof Item ? thisItem : (args.item || null), move: typeof move !== "undefined" ? move : (args.move || null) });
            actor.showFloatyText(`金刚护体抵消 ${absorb}`, {fill: "#ffd700"});
        }
    }
}

